import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const badgeVariants = cva(
  "inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2",
  {
    variants: {
      variant: {
        default: "border-transparent bg-primary text-primary-foreground hover:bg-primary/80",
        secondary:
          "border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80",
        destructive:
          "border-transparent bg-destructive text-destructive-foreground hover:bg-destructive/80",
        outline: "text-foreground",
        bubble:
          "rounded-[var(--radius-bubble-pill,9999px)] bg-[var(--glass-tint-card)] border-[var(--glass-edge)] text-foreground backdrop-blur-[12px] backdrop-saturate-[140%] [box-shadow:var(--shadow-bubble-rest)]",
        bull: "rounded-[var(--radius-bubble-pill,9999px)] border-[var(--color-bull-soft,transparent)] bg-[var(--color-bull-soft)] text-[var(--color-bull-fg)] backdrop-blur-[8px]",
        bear: "rounded-[var(--radius-bubble-pill,9999px)] border-[var(--color-bear-soft,transparent)] bg-[var(--color-bear-soft)] text-[var(--color-bear-fg)] backdrop-blur-[8px]",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

export interface BadgeProps
  extends React.HTMLAttributes<HTMLDivElement>, VariantProps<typeof badgeVariants> {}

function Badge({ className, variant, ...props }: BadgeProps) {
  return <div className={cn(badgeVariants({ variant }), className)} {...props} />;
}

export { Badge, badgeVariants };
